import { NextRequest, NextResponse } from "next/server";
import { readFile } from "node:fs/promises";
import path from "node:path";

/**
 * GET /api/sdks/[slug]/[lang] — download a listing's generated SDK zip.
 * SDKs are generated by APIMatic Codegen at publish time into data/sdks/.
 */
export async function GET(_req: NextRequest, ctx: { params: Promise<{ slug: string; lang: string }> }) {
  const { slug, lang } = await ctx.params;
  if (!/^[a-z0-9-]+$/.test(slug) || !/^[a-z0-9-]+$/.test(lang)) {
    return NextResponse.json({ error: "bad request" }, { status: 400 });
  }
  const file = path.join(process.cwd(), "data", "sdks", slug, `${slug}-${lang}-sdk.zip`);
  try {
    const zip = await readFile(file);
    return new NextResponse(new Uint8Array(zip), {
      headers: {
        "Content-Type": "application/zip",
        "Content-Disposition": `attachment; filename="${slug}-${lang}-sdk.zip"`,
      },
    });
  } catch {
    return NextResponse.json({ error: "SDK not found — publish the listing with APIMATIC_API_KEY set to generate SDKs" }, { status: 404 });
  }
}
